INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_111'), 1, 'A Service finds pods only through its selector: compare the selector key by key with the labels the pods really carry (`kubectl get pods --show-labels`).'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_111'), 2, 'Ask who would create a replacement pod. A Deployment''s ReplicaSet watches its pod count; what watches a pod that was created on its own?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_111'), 3, 'Read the endpoint address: which port does it name, and which port does the container listen on? `port` is what clients call, `targetPort` is where the traffic lands.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_111');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_111'), 'The api pods run, yet every call through the Service fails:

```text
$ kubectl -n rice-rocket get pods --show-labels
NAME                   READY   STATUS    LABELS
api-7d9f8c6b5d-2kxqv   1/1     Running   app.kubernetes.io/name=api,pod-template-hash=7d9f8c6b5d
api-7d9f8c6b5d-8wz4n   1/1     Running   app.kubernetes.io/name=api,pod-template-hash=7d9f8c6b5d

$ kubectl -n rice-rocket get service api -o jsonpath=''{.spec.selector}''
{"app":"api"}

$ kubectl -n rice-rocket get endpointslices -l kubernetes.io/service-name=api
NAME        ADDRESSTYPE   PORTS     ENDPOINTS   AGE
api-x7c2m   IPv4          <unset>   <unset>     6m
```

Statement: "The pods are healthy; the Service has no endpoints because its selector `app: api` matches no pod label, so it must select `app.kubernetes.io/name: api`."', 'single_choice'::question_type, 'True. A Service sends traffic to the ready pods whose labels match every key of its selector. The pods carry `app.kubernetes.io/name=api`, not `app=api`, so the EndpointSlice is empty and connections are refused. Nothing is wrong with the pods. The misconception is that a Service follows the Deployment of the same name: it only follows labels.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_111'), 'During a cluster upgrade the provider drained node `pool-a-1`. A debug copy of the api that someone started with a plain Pod manifest is gone:

```yaml
apiVersion: v1
kind: Pod
metadata:
  name: api-debug
  namespace: rice-rocket
spec:
  containers:
    - name: api
      image: ghcr.io/rice-rocket/api:1.4.0
```

```text
$ kubectl -n rice-rocket get pods
NAME                   READY   STATUS    RESTARTS   AGE
api-7d9f8c6b5d-5m2rt   1/1     Running   0          2m
api-7d9f8c6b5d-8wz4n   1/1     Running   0          3d
$ kubectl -n rice-rocket get pod api-debug
Error from server (NotFound): pods "api-debug" not found
```

Statement: "The scheduler moves a bare Pod to another node when its node is drained, just as it does for a Deployment''s pods, so `api-debug` will come back by itself."', 'single_choice'::question_type, 'False. A drain evicts pods; nothing recreates a pod that no controller owns, so `api-debug` is simply deleted. The Deployment''s pod came back (`api-7d9f8c6b5d-5m2rt`, 2 minutes old) because its ReplicaSet saw one replica missing and created a new pod, which the scheduler placed on another node. The scheduler never moves running pods; controllers replace them. Run real workloads as Deployments, even with one replica.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_111'), 'The selector is fixed and the Service has endpoints, but calls still fail:

```yaml
# Service api
  ports:
    - port: 80
      targetPort: 80
# container api
          ports:
            - name: http
              containerPort: 3000
```

```text
$ kubectl -n rice-rocket get endpointslices -l kubernetes.io/service-name=api
NAME        ADDRESSTYPE   PORTS   ENDPOINTS              AGE
api-x7c2m   IPv4          80      10.8.1.14,10.8.2.9     9m
$ kubectl -n rice-rocket run curl --rm -it --image=curlimages/curl -- curl -sS http://api/health
curl: (7) Failed to connect to api port 80: Connection refused
```

Statement: "The endpoints point at port 80 on the pods, where nothing listens; `targetPort` must be the container''s port, `3000` or its name `http`."', 'single_choice'::question_type, 'True. `port: 80` is what clients call (`http://api`), and `targetPort` is the port on the pod the traffic is forwarded to. The EndpointSlice lists the pods on port 80, but the api listens on 3000, so each connection is refused at the pod. `targetPort: http` follows the container''s named port, so a later port change in the image needs one edit. The misconception is that the Service port and the container port have to be the same number.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_111') AND order_index = 3)
    RETURNING id
)
