-- challenge chal_coding_k8s_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_k8s_122', (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-k8s-1-2' AND is_deleted = false LIMIT 1), 'api-config-and-secrets', 'Wire the api''s config and secrets', 'Rice Rocket''s first manifest wrote the database password and the JWT secret as plain `value:` entries, and they ended up in git. The team has since created the Secret `api-secrets` out of band (keys `db-password` and `jwt-secret`); it is not in this file and must stay out of it. The editor holds `k8s/api.yaml` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: the ConfigMap `api-config` holds the settings that are not secret (`NODE_ENV=production`, `PORT=3000`, `DATABASE_HOST=db.internal.ricerocket.vn`, `DATABASE_USER=rocket`, `DATABASE_NAME=rocket`, `JWT_SECRET_FILE=/run/secrets/jwt_secret`) and every key reaches the container as a variable; `DATABASE_PASSWORD` comes from the Secret''s `db-password` key; the Secret''s `jwt-secret` key is the file `/run/secrets/jwt_secret`, mounted read-only, and a rotated secret reaches running pods without a restart; no secret value is written in the file. Run grades the file with a kubelet simulator that starts the api container against the cluster''s Secret.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
