-- challenge chal_quiz_k8s_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_k8s_131', (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-k8s-1-3' AND is_deleted = false LIMIT 1), 'probes-quiz', 'Read the probe incidents', 'Three statements about what Rice Rocket''s probes did in production. Decide whether each one is true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_131');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_131'), 1, 'Each probe kind has one consequence when it fails. Which one restarts the container, which one only changes whether the pod gets traffic, and which one only delays the other two?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_131'), 2, 'Ask what a restart can fix. If every pod fails the same check because of something outside the pods, what does restarting all of them at once do to the service?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_131'), 3, 'Multiply `failureThreshold` by `periodSeconds` for each probe, and check in the docs which probes run while a startup probe has not succeeded yet.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_131'), 'One api pod has been unready for six minutes:

```text
$ kubectl -n rice-rocket get pods -l app=api
NAME                   READY   STATUS    RESTARTS   AGE
api-7d9f8c6b5d-4kq2x   0/1     Running   0          6m
api-7d9f8c6b5d-9wz7m   1/1     Running   0          2d

$ kubectl -n rice-rocket describe pod api-7d9f8c6b5d-4kq2x | tail -1
  Warning  Unhealthy  12s (x71 over 6m)  kubelet  Readiness probe failed: HTTP probe failed with statuscode: 503
```

Statement: "After `failureThreshold` failed readiness checks the kubelet restarts the container, so the RESTARTS column of this pod will keep growing until it recovers."', 'single_choice'::question_type, 'False. A failing readiness probe never restarts anything: the kubelet marks the pod unready and the EndpointSlice controller removes it from the Service, so it stops getting traffic. RESTARTS stays 0, as the output shows after 71 failures. Only a failing liveness probe (or a failing startup probe) restarts the container. The misconception is that every probe is a health check that heals by restarting.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_131'), 'During a 40 second failover of the managed Postgres, every api pod restarted at the same time and the site was down for two minutes:

```yaml
livenessProbe:
  httpGet:
    path: /ready        # runs SELECT 1 against Postgres
    port: http
  periodSeconds: 10
  failureThreshold: 3
```

```text
$ kubectl -n rice-rocket get pods -l app=api
NAME                   READY   STATUS    RESTARTS     AGE
api-7d9f8c6b5d-4kq2x   0/1     Running   1 (8s ago)   2d
api-7d9f8c6b5d-9wz7m   0/1     Running   1 (9s ago)   2d
api-7d9f8c6b5d-r2t5p   0/1     Running   1 (8s ago)   2d
```

Statement: "Pointing liveness at `/ready` is right: a pod that cannot reach its database is broken, and a restart is how Kubernetes replaces it with a healthy one."', 'single_choice'::question_type, 'False. A restart cannot fix a database that is down for everyone: all three pods failed liveness together, restarted together, and each then spent its boot time (about 20 s here) unable to serve even after Postgres came back, which stretched a 40 s blip into an outage. Liveness should answer only "is this process stuck?" (`/health`); dependency checks belong in readiness, which takes the pod out of the Service without killing it. The misconception is that liveness is a general health check.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_131'), 'On a freshly added node the api took 44 seconds to load its price cache:

```yaml
startupProbe:
  httpGet: { path: /health, port: http }
  periodSeconds: 2
  failureThreshold: 30
livenessProbe:
  httpGet: { path: /health, port: http }
  periodSeconds: 10
  failureThreshold: 3
```

```text
  Warning  Unhealthy  2s (x22 over 44s)  kubelet  Startup probe failed: Get "http://10.42.3.17:3000/health": dial tcp 10.42.3.17:3000: connect: connection refused
  Normal   Started    ...
```

Statement: "The app has up to 60 seconds (30 x 2 s) to answer `/health`, and liveness does not run until the startup probe has succeeded, so this slow start does not end in a restart."', 'single_choice'::question_type, 'True. While a startup probe is configured and has not yet succeeded, the kubelet does not run the liveness and readiness probes. It allows `failureThreshold x periodSeconds` = 60 s; 22 failures over 44 s stay under 30, the probe then succeeds and liveness takes over with its own 30 s window for a process that later hangs. Without the startup probe, the liveness probe alone (3 x 10 s) would have restarted the container at about 30 s, every time, into CrashLoopBackOff.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_131') AND order_index = 3)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_k8s_132 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_k8s_132', (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-k8s-1-3' AND is_deleted = false LIMIT 1), 'fix-api-probes', 'Fix the api probes', 'The api''s probes caused three incidents: liveness on `/ready` restarted every pod during a 40 s Postgres failover; with no readiness probe, pods got traffic while they were still booting (about 20 s, up to 50 s on a cold node), which showed as 502s on every rollout; and a later liveness probe with a 5 s initial delay killed slow starts into CrashLoopBackOff. The editor holds the api Deployment with its three probes missing, each marked by a `# [ ]` line; some pieces are the old, wrong probes. The api answers `GET /health` once the process is up and `GET /ready` only while it can also reach Postgres. Fill the lines so that: a boot of up to 50 s never ends in a restart; a pod gets traffic only while `/ready` answers, and leaves the Service within 10 s when it stops answering; a database outage never restarts a pod; a process that hangs is restarted within about 30 s. Run plays each scenario on a one-pod timeline with the documented probe rules.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
