INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_132'), 1, 'For each scenario (slow boot, database failover, hung process), ask which endpoint stops answering, which probe looks at it, and what that probe does after `failureThreshold` failures.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_132'), 2, 'Look at the three probe kinds (`startupProbe`, `readinessProbe`, `livenessProbe`) and their fields `httpGet.path`, `httpGet.port`, `periodSeconds` and `failureThreshold`. A TCP check succeeds as soon as the port listens.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_132'), 3, 'A worker that needs up to 2 minutes to warm up, should leave the Service within 6 s when its queue is unreachable, and be restarted after 45 s stuck: `startupProbe` on `/livez` with `periodSeconds: 5, failureThreshold: 24`; `readinessProbe` on `/readyz` with `periodSeconds: 3, failureThreshold: 2`; `livenessProbe` on `/livez` with `periodSeconds: 15, failureThreshold: 3`.');
