INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_141'), 1, 'Read the condition, not the command: what does `ProgressDeadlineExceeded` change in the cluster, and what is left for a person or a pipeline to do?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_141'), 2, 'Percentages in `rollingUpdate` are turned into pod counts. One field is rounded up and the other down; which rounding keeps more pods serving?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_141'), 3, 'With `maxUnavailable: 0`, list which pods the controller is allowed to remove before a new pod is available, and which pods the Service keeps sending traffic to.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_141');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_141'), 'The 1.5.0 release crashes on start. The deploy pipeline shows:

```text
$ kubectl rollout status deployment/api -n rice-rocket --timeout=15m
Waiting for deployment "api" rollout to finish: 1 out of 6 new replicas have been updated...
error: deployment "api" exceeded its progress deadline

$ kubectl get deploy api -n rice-rocket -o jsonpath=''{.status.conditions[?(@.type=="Progressing")].reason}''
ProgressDeadlineExceeded
```

Statement: "Now that the progress deadline is exceeded, Kubernetes scales the new ReplicaSet back to 0 and restores the previous version on its own; the pipeline only has to report the failure."', 'single_choice'::question_type, 'False. `progressDeadlineSeconds` only sets the `Progressing` condition to `False` with reason `ProgressDeadlineExceeded`; the Deployment controller takes no further action, and the new ReplicaSet keeps its crashing pod. Rolling back is a decision someone makes: `kubectl rollout undo deployment/api`, or a pipeline step that runs it when `rollout status` fails. The misconception is that the deadline is an automatic rollback switch; it is a signal that tools like `kubectl rollout status` can fail on.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_141') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_141'), 'The api runs 6 replicas with no `strategy:` in the manifest. During the 12:00 rollout:

```text
$ kubectl get deploy api -n rice-rocket -o jsonpath=''{.spec.strategy}''
{"rollingUpdate":{"maxSurge":"25%","maxUnavailable":"25%"},"type":"RollingUpdate"}

$ kubectl get rs -n rice-rocket -l app=api
NAME             DESIRED   CURRENT   READY   AGE
api-7c9f6d5b8d   5         5         5       3d
api-5f4b8c7d9a   3         3         0       12s
```

Statement: "25% of 6 is 1.5; maxSurge rounds up to 2 and maxUnavailable rounds down to 1, so the rollout runs with up to 8 pods but can leave only 5 serving, which is what happened at lunch."', 'single_choice'::question_type, 'True. For percentages, Kubernetes rounds `maxSurge` up and `maxUnavailable` down: 6 x 25% gives 2 extra pods allowed and 1 pod allowed to be unavailable. The listing shows exactly that: 5 old pods ready plus 3 new pods not ready yet (8 in total), so only 5 pods serve traffic during the peak. Setting `maxSurge: 1` and `maxUnavailable: 0` keeps all 6 serving at the cost of a slower rollout. The misconception is that the default strategy never reduces capacity.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_141') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_141'), 'The strategy is now `maxSurge: 1`, `maxUnavailable: 0`, and the 1.5.2 image never passes its readiness probe:

```text
$ kubectl get pods -n rice-rocket -l app=api
NAME                   READY   STATUS    RESTARTS   AGE
api-7c9f6d5b8d-2xk4p   1/1     Running   0          3d
api-7c9f6d5b8d-8hq7m   1/1     Running   0          3d
api-7c9f6d5b8d-c5w2n   1/1     Running   0          3d
api-7c9f6d5b8d-jd9rt   1/1     Running   0          3d
api-7c9f6d5b8d-q7zlv   1/1     Running   0          3d
api-7c9f6d5b8d-x4mbf   1/1     Running   0          3d
api-5d8b7f6c4e-k2p9s   0/1     Running   0          4m
```

Statement: "The rollout is stuck, but customers see no errors: no old pod may go before a new one is available, and the Service sends traffic only to the 6 ready old pods."', 'single_choice'::question_type, 'True. With `maxUnavailable: 0` the controller may remove an old pod only after a new pod has been available (ready for `minReadySeconds`); the new pod never gets there, so all 6 old pods stay. The not-ready pod is not an endpoint of the Service, so it receives no traffic. The rollout simply stops after one surge pod, and the progress deadline reports it. The misconception is that a stuck rollout always means an outage; with this strategy it means a release that did not happen.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_141') AND order_index = 3)
    RETURNING id
)
