INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_k8s_142', (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-k8s-2-1' AND is_deleted = false LIMIT 1), 'safe-rolling-update', 'Make the api rollout safe', 'Rice Rocket''s api runs 6 replicas, and the lunch peak needs all 6. The last releases dropped to 5 serving pods with the default strategy, shipped `latest` so nobody knew which version ran, and hung for 10 minutes on a crashing image. The editor holds the api Deployment with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: a rollout adds one pod before it removes one and never has fewer than 6 serving; a new pod counts as available only after 10 seconds of passing readiness; a stuck rollout is reported after 5 minutes; the last 5 versions stay available for `kubectl rollout undo`; and the image is the exact version `1.5.1`. Run grades the file with a simulator of the Deployment controller that rolls out a healthy and a never-ready image.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
