VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_142'), 1, 'For each requirement, find the Deployment field that controls it: how many pods may be added or missing during a rollout, when a ready pod counts, when a rollout is called stuck, how many old ReplicaSets are kept.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_142'), 2, 'Look at `spec.strategy.rollingUpdate` (`maxSurge`, `maxUnavailable`), `spec.minReadySeconds`, `spec.progressDeadlineSeconds`, `spec.revisionHistoryLimit`, and the tag in `image:`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_142'), 3, 'A worker Deployment with 4 replicas that may lose at most one pod, adds none, waits 30 seconds per pod, gives up after 10 minutes and keeps 3 versions: `strategy: { type: RollingUpdate, rollingUpdate: { maxSurge: 0, maxUnavailable: 1 } }`, `minReadySeconds: 30`, `progressDeadlineSeconds: 600`, `revisionHistoryLimit: 3`, `image: ghcr.io/acme/worker:2.3.0`.');
