WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_151'), 'The api container has `limits: { cpu: 500m, memory: 768Mi }`. During a burst of orders:

```text
$ kubectl top pod api-5c9d7f6b8-2xkqz --containers
POD                   NAME   CPU(cores)   MEMORY(bytes)
api-5c9d7f6b8-2xkqz   api    500m         402Mi

# container_cpu_cfs_throttled_periods_total / container_cpu_cfs_periods_total
api   0.71
```

Statement: "If the burst keeps the api above 500m for long enough, the kubelet restarts the container with OOMKilled, the same way it does for memory."', 'single_choice'::question_type, 'False. CPU is a compressible resource: at its limit the kernel''s CFS quota **throttles** the container (71% of periods were throttled here) and requests take longer, but the container is never killed or restarted for using CPU. Memory cannot be taken back, so a container over its memory limit is killed (OOMKilled). The fix for this p99 spike is a higher CPU limit or none (keep the request), not more memory. The misconception is that both limits end the same way.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_151') AND order_index = 2)
    RETURNING id
)
