-- challenge chal_coding_k8s_152 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_k8s_152', (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-k8s-2-2' AND is_deleted = false LIMIT 1), 'node-capacity-planner', 'Plan a node: requests, QoS, OOMKilled and eviction', 'Before setting `resources:` on every Rice Rocket workload, the team wants a small tool that shows what one node does with a list of pods. The editor holds `plan-node.js` with its key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. `planNode(node, pods)` must: read quantities (`250m` and `1` for CPU; `Ki/Mi/Gi` are powers of 1024, `k/M/G` powers of 1000, a bare number is bytes); bind pods in arrival order while the sum of their **requests** fits the node''s allocatable (a container with only a limit requests its limit; check CPU first, then memory; a pod that does not fit is pending with reason `Insufficient cpu` or `Insufficient memory`); give every pod a QoS class (`BestEffort` when no container sets any request or limit; `Guaranteed` when every container has CPU and memory limits and its requests equal them; otherwise `Burstable`); for each bound container report `OOMKilled` when its memory usage is above its memory limit, else `Throttled` when its CPU usage is above its CPU limit, else `Running`; and rank the bound pods for eviction under memory pressure: pods using more memory than they request first, then lower `priority` first, then the largest usage minus requests first, then arrival order. Run grades it on scripted nodes and pods.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_152');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_152'), 1, 'Take the first test on paper: add up what each api pod asks for, not what it uses, and stop when the next pod does not fit into 1930m.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_152'), 2, 'Each helper answers one question: what is this quantity in millicores or bytes, how much does the pod request, which QoS class is it, what happens to a container over a limit, who goes first when memory runs out. The loop only calls them.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_152'), 3, 'A disk planner that binds volumes in order while their requested size fits the free space: `if (want > free) { pending.push({ name, reason: "Insufficient storage" }); continue; } free -= want;`, where `want` is `request ?? limit`, and `"10G"` is `10 * 1e9` bytes while `"10Gi"` is `10 * 1024 ** 3`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_152'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"fits-on-node","label":"Bind the pod only if its requests fit what is left","code":"if (want.cpu > free.cpu) {\n    pending.push({ name: pod.name, reason: \"Insufficient cpu\" });\n    continue;\n}\nif (want.memory > free.memory) {\n    pending.push({ name: pod.name, reason: \"Insufficient memory\" });\n    continue;\n}\nfree.cpu -= want.cpu;\nfree.memory -= want.memory;"},{"id":"parse-quantity","label":"Turn \"250m\", \"1\", \"512Mi\", \"512M\" into millicores and bytes","code":"function cpuMillis(q) {\n    const s = String(q ?? 0).trim();\n    return s.endsWith(\"m\") ? Number(s.slice(0, -1)) : Math.round(Number(s) * 1000);\n}\n\nfunction memoryBytes(q) {\n    const units = { Ki: 1024, Mi: 1024 ** 2, Gi: 1024 ** 3, Ti: 1024 ** 4, k: 1e3, M: 1e6, G: 1e9, T: 1e12 };\n    const m = String(q ?? 0).trim().match(/^([\\d.]+)([A-Za-z]*)$/);\n    return Math.round(Number(m[1]) * (units[m[2]] ?? 1));\n}"},{"id":"effective-requests","label":"Sum the pod''s requests; a limit alone is also the request","code":"function podRequests(pod) {\n    let cpu = 0;\n    let memory = 0;\n    for (const c of pod.containers) {\n        const { requests, limits } = resourcesOf(c);\n        cpu += cpuMillis(requests.cpu ?? limits.cpu ?? 0);\n        memory += memoryBytes(requests.memory ?? limits.memory ?? 0);\n    }\n    return { cpu, memory };\n}"},{"id":"qos-class","label":"Guaranteed, Burstable or BestEffort for the whole pod","code":"function qosClass(pod) {\n    const all = pod.containers.map(resourcesOf);\n    if (all.every(({ requests, limits }) => !Object.keys(requests).length && !Object.keys(limits).length)) return \"BestEffort\";\n    const guaranteed = all.every(({ requests, limits }) => [\"cpu\", \"memory\"].every((r) => {\n        if (limits[r] === undefined) return false;\n        const request = requests[r] ?? limits[r];\n        return r === \"cpu\" ? cpuMillis(request) === cpuMillis(limits[r]) : memoryBytes(request) === memoryBytes(limits[r]);\n    }));\n    return guaranteed ? \"Guaranteed\" : \"Burstable\";\n}"},{"id":"container-state","label":"Over the memory limit or over the CPU limit","code":"function containerState(c) {\n    const { limits } = resourcesOf(c);\n    const usage = c.usage || {};\n    if (limits.memory !== undefined && memoryBytes(usage.memory ?? 0) > memoryBytes(limits.memory)) return \"OOMKilled\";\n    if (limits.cpu !== undefined && cpuMillis(usage.cpu ?? 0) > cpuMillis(limits.cpu)) return \"Throttled\";\n    return \"Running\";\n}"},{"id":"eviction-rank","label":"Order pods for eviction when the node runs out of memory","code":"function evictionOrder(pods) {\n    const ranked = pods.map((pod, arrival) => {\n        const requested = podRequests(pod).memory;\n        const used = pod.containers.reduce((sum, c) => sum + memoryBytes((c.usage && c.usage.memory) ?? 0), 0);\n        return { name: pod.name, arrival, over: used > requested, priority: pod.priority ?? 0, excess: used - requested };\n    });\n    ranked.sort((a, b) => (b.over - a.over) || (a.priority - b.priority) || (b.excess - a.excess) || (a.arrival - b.arrival));\n    return ranked.map((p) => p.name);\n}"},{"id":"cpu-over-limit-oom","label":"Over the memory limit or over the CPU limit","code":"function containerState(c) {\n    const { limits } = resourcesOf(c);\n    const usage = c.usage || {};\n    const overMemory = limits.memory !== undefined && memoryBytes(usage.memory ?? 0) > memoryBytes(limits.memory);\n    const overCpu = limits.cpu !== undefined && cpuMillis(usage.cpu ?? 0) > cpuMillis(limits.cpu);\n    return overMemory || overCpu ? \"OOMKilled\" : \"Running\";\n}","distractor":true},{"id":"fits-by-usage","label":"Bind the pod only if its requests fit what is left","code":"const used = pod.containers.reduce((sum, c) => ({\n    cpu: sum.cpu + cpuMillis((c.usage && c.usage.cpu) ?? 0),\n    memory: sum.memory + memoryBytes((c.usage && c.usage.memory) ?? 0),\n}), { cpu: 0, memory: 0 });\nif (used.cpu > free.cpu) {\n    pending.push({ name: pod.name, reason: \"Insufficient cpu\" });\n    continue;\n}\nif (used.memory > free.memory) {\n    pending.push({ name: pod.name, reason: \"Insufficient memory\" });\n    continue;\n}\nfree.cpu -= used.cpu;\nfree.memory -= used.memory;","distractor":true},{"id":"qos-memory-only","label":"Guaranteed, Burstable or BestEffort for the whole pod","code":"function qosClass(pod) {\n    const all = pod.containers.map(resourcesOf);\n    if (all.every(({ requests, limits }) => !Object.keys(requests).length && !Object.keys(limits).length)) return \"BestEffort\";\n    // Requests equal to limits for memory: the pod cannot be OOMKilled for going over its request.\n    const guaranteed = all.every(({ requests, limits }) => limits.memory !== undefined\n        && memoryBytes(requests.memory ?? limits.memory) === memoryBytes(limits.memory));\n    return guaranteed ? \"Guaranteed\" : \"Burstable\";\n}","distractor":true},{"id":"units-all-binary","label":"Turn \"250m\", \"1\", \"512Mi\", \"512M\" into millicores and bytes","code":"function cpuMillis(q) {\n    const s = String(q ?? 0).trim();\n    return s.endsWith(\"m\") ? Number(s.slice(0, -1)) : Math.round(Number(s) * 1000);\n}\n\nfunction memoryBytes(q) {\n    // M and Mi are the same thing, so are G and Gi.\n    const units = { K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };\n    const m = String(q ?? 0).trim().match(/^([\\d.]+)([A-Za-z]?)/);\n    return Math.round(Number(m[1]) * (units[m[2].toUpperCase()] ?? 1));\n}","distractor":true}]'::jsonb)
