VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_152'), 'Binds by requests, not by usage: the third api replica stays Pending on cpu', '{"node":{"name":"pool-a-1","allocatable":{"cpu":"1930m","memory":"3.3Gi"}},"pods":[{"name":"api-a","containers":[{"name":"api","resources":{"requests":{"cpu":"700m","memory":"512Mi"},"limits":{"memory":"768Mi"}},"usage":{"cpu":"100m","memory":"300Mi"}}]},{"name":"api-b","containers":[{"name":"api","resources":{"requests":{"cpu":"700m","memory":"512Mi"},"limits":{"memory":"768Mi"}},"usage":{"cpu":"100m","memory":"300Mi"}}]},{"name":"api-c","containers":[{"name":"api","resources":{"requests":{"cpu":"700m","memory":"512Mi"},"limits":{"memory":"768Mi"}},"usage":{"cpu":"100m","memory":"300Mi"}}]}]}', '{"scheduled":["api-a","api-b"],"pending":[{"name":"api-c","reason":"Insufficient cpu"}],"qos":{"api-a":"Burstable","api-b":"Burstable","api-c":"Burstable"},"containers":{"api-a/api":"Running","api-b/api":"Running"},"evictionOrder":["api-a","api-b"]}', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_152'), 'Memory over its limit is OOMKilled; CPU over its limit is only throttled', '{"node":{"name":"pool-a-1","allocatable":{"cpu":"1930m","memory":"3.3Gi"}},"pods":[{"name":"api-a","containers":[{"name":"api","resources":{"requests":{"cpu":"250m","memory":"256Mi"},"limits":{"cpu":"500m","memory":"512Mi"}},"usage":{"cpu":"900m","memory":"700Mi"}}]},{"name":"api-b","containers":[{"name":"api","resources":{"requests":{"cpu":"250m","memory":"256Mi"},"limits":{"cpu":"500m","memory":"512Mi"}},"usage":{"cpu":"900m","memory":"300Mi"}}]},{"name":"api-c","containers":[{"name":"api","resources":{"requests":{"cpu":"250m","memory":"256Mi"},"limits":{"cpu":"500m","memory":"512Mi"}},"usage":{"cpu":"200m","memory":"300Mi"}}]}]}', '{"scheduled":["api-a","api-b","api-c"],"pending":[],"qos":{"api-a":"Burstable","api-b":"Burstable","api-c":"Burstable"},"containers":{"api-a/api":"OOMKilled","api-b/api":"Throttled","api-c/api":"Running"},"evictionOrder":["api-a","api-b","api-c"]}', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_152'), 'QoS: Guaranteed needs CPU and memory requests equal to limits in every container', '{"node":{"name":"pool-a-1","allocatable":{"cpu":"1930m","memory":"3.3Gi"}},"pods":[{"name":"matcher","containers":[{"name":"matcher","resources":{"limits":{"cpu":"500m","memory":"512Mi"}},"usage":{"cpu":"300m","memory":"400Mi"}}]},{"name":"api","containers":[{"name":"api","resources":{"requests":{"cpu":"250m","memory":"512Mi"},"limits":{"memory":"512Mi"}},"usage":{"cpu":"200m","memory":"400Mi"}}]},{"name":"debug","containers":[{"name":"shell","resources":{},"usage":{"cpu":"10m","memory":"20Mi"}}]},{"name":"web","containers":[{"name":"nginx","resources":{"requests":{"cpu":"100m","memory":"64Mi"},"limits":{"cpu":"100m","memory":"64Mi"}},"usage":{"cpu":"50m","memory":"40Mi"}},{"name":"log-shipper","resources":{},"usage":{"cpu":"5m","memory":"30Mi"}}]}]}', '{"scheduled":["matcher","api","debug","web"],"pending":[],"qos":{"matcher":"Guaranteed","api":"Burstable","debug":"BestEffort","web":"Burstable"},"containers":{"matcher/matcher":"Running","api/api":"Running","debug/shell":"Running","web/nginx":"Running","web/log-shipper":"Running"},"evictionOrder":["debug","web","matcher","api"]}', 5, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_152'), 'Eviction: pods over their memory requests go first, then low priority, then the largest excess', '{"node":{"name":"pool-a-1","allocatable":{"cpu":"1930m","memory":"3.3Gi"}},"pods":[{"name":"api","priority":1000,"containers":[{"name":"api","resources":{"limits":{"cpu":"250m","memory":"512Mi"}},"usage":{"cpu":"200m","memory":"400Mi"}}]},{"name":"courier-matcher","containers":[{"name":"matcher","resources":{"requests":{"cpu":"200m","memory":"256Mi"},"limits":{"memory":"1Gi"}},"usage":{"cpu":"150m","memory":"600Mi"}}]},{"name":"debug","containers":[{"name":"shell","resources":{},"usage":{"cpu":"10m","memory":"50Mi"}}]},{"name":"report-export","containers":[{"name":"export","resources":{"requests":{"cpu":"500m","memory":"1Gi"},"limits":{"memory":"1536Mi"}},"usage":{"cpu":"400m","memory":"900Mi"}}]}]}', '{"scheduled":["api","courier-matcher","debug","report-export"],"pending":[],"qos":{"api":"Guaranteed","courier-matcher":"Burstable","debug":"BestEffort","report-export":"Burstable"},"containers":{"api/api":"Running","courier-matcher/matcher":"Running","debug/shell":"Running","report-export/export":"Running"},"evictionOrder":["courier-matcher","debug","report-export","api"]}', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_152'), 'Units: 512M is 512,000,000 bytes and 512Mi is 536,870,912', '{"node":{"name":"pool-small-1","allocatable":{"cpu":"2","memory":"1060M"}},"pods":[{"name":"api","containers":[{"name":"api","resources":{"requests":{"cpu":"250m","memory":"512Mi"},"limits":{"memory":"600M"}},"usage":{"cpu":"100m","memory":"590Mi"}}]},{"name":"courier-matcher","containers":[{"name":"matcher","resources":{"requests":{"cpu":"250m","memory":"512M"}},"usage":{"cpu":"100m","memory":"300Mi"}}]}]}', '{"scheduled":["api","courier-matcher"],"pending":[],"qos":{"api":"Burstable","courier-matcher":"Burstable"},"containers":{"api/api":"OOMKilled","courier-matcher/matcher":"Running"},"evictionOrder":["api","courier-matcher"]}', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_152'), 'A limit alone is also the request; arrival order decides who stays Pending', '{"node":{"name":"pool-a-1","allocatable":{"cpu":"1930m","memory":"3.3Gi"}},"pods":[{"name":"report-export","containers":[{"name":"export","resources":{"limits":{"cpu":"1500m","memory":"1Gi"}},"usage":{"cpu":"900m","memory":"700Mi"}}]},{"name":"api","containers":[{"name":"api","resources":{"requests":{"cpu":"250m","memory":"256Mi"}},"usage":{"cpu":"100m","memory":"200Mi"}}]},{"name":"web","containers":[{"name":"nginx","resources":{"requests":{"cpu":"100m","memory":"3Gi"}},"usage":{"cpu":"10m","memory":"50Mi"}}]},{"name":"courier-matcher","containers":[{"name":"matcher","resources":{"requests":{"cpu":"200m","memory":"64Mi"}},"usage":{"cpu":"50m","memory":"40Mi"}}]}]}', '{"scheduled":["report-export","api"],"pending":[{"name":"web","reason":"Insufficient memory"},{"name":"courier-matcher","reason":"Insufficient cpu"}],"qos":{"report-export":"Guaranteed","api":"Burstable","web":"Burstable","courier-matcher":"Burstable"},"containers":{"report-export/export":"Running","api/api":"Running"},"evictionOrder":["api","report-export"]}', 5, false, true, 6);
