INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_k8s_162', (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-k8s-2-3' AND is_deleted = false LIMIT 1), 'api-autoscaler', 'Autoscale the api for the lunch and dinner peaks', 'Rice Rocket''s api needs 3 pods at night and up to 3 times more at 11:00 and 18:00. The first autoscaler showed `<unknown>/70%` and never scaled, a release applied during the peak cut 9 pods back to 3, and after the peak the pod count went up and down every minute. The editor holds `k8s/api.yaml` (the api Deployment and its HorizontalPodAutoscaler) with key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: each api pod reserves 250m CPU and 256Mi memory (512Mi memory limit); the HPA resizes the api Deployment between 3 and 12 pods, aiming at 70% of the reserved CPU; it may double the pods each minute but removes pods only after 5 calm minutes; and applying the file during a peak never changes the pod count. Run grades the file with a simulator of the autoscaler''s documented algorithm on a recorded day of load.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
