VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_162'), 1, 'Walk through the three incidents: what does the autoscaler divide the CPU use by, which field of the Deployment does `kubectl apply` write back, and what makes the autoscaler wait before it removes pods?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_162'), 2, 'Look at `resources.requests` of the container, `spec.replicas` of the Deployment (and what happens when it is absent), and in the HPA: `scaleTargetRef`, `minReplicas` / `maxReplicas`, `metrics[].resource.target` (`type: Utilization` with `averageUtilization`), and `behavior.scaleUp` / `behavior.scaleDown`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_162'), 3, 'A worker that should stay between 2 and 8 pods at 60% of a 500m request, grow by at most 4 pods a minute and shrink after 10 calm minutes: `resources: { requests: { cpu: 500m } }` on its container, no `replicas:` in its Deployment, and an HPA with `minReplicas: 2`, `maxReplicas: 8`, `metrics: [{ type: Resource, resource: { name: cpu, target: { type: Utilization, averageUtilization: 60 } } }]`, `behavior: { scaleUp: { policies: [{ type: Pods, value: 4, periodSeconds: 60 }] }, scaleDown: { stabilizationWindowSeconds: 600 } }`.');
