INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_k8s_171', (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-k8s-3-1' AND is_deleted = false LIMIT 1), 'gateway-routing-quiz', 'Read the Gateway API routes', 'Three statements about what Rice Rocket saw while moving its routing from Ingress to the Gateway API. Decide whether each one is true.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
