INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_171'), 1, 'PathPrefix compares whole path segments split on `/`, not characters. Which segments does `/apiary-docs` have?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_171'), 2, 'Look at who writes which object: the Gateway carries `allowedRoutes`, the HTTPRoute only asks to attach. Which side decides whether the request is accepted?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_171'), 3, 'A Service has its own `port` and a `targetPort` that points at the container. Which of the two does a `backendRef` name?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_171');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_171'), 'The `site` route sends the web app''s API calls to the api:

```yaml
rules:
  - matches:
      - path:
          type: PathPrefix
          value: /api
    backendRefs:
      - name: api
        port: 80
  - backendRefs:
      - name: web
        port: 80
```

The marketing team publishes a page at `https://ricerocket.vn/apiary-docs`.

Statement: "The page is sent to the api, because `/apiary-docs` starts with the prefix `/api`."', 'single_choice'::question_type, 'False. A PathPrefix match compares the path element by element, split on `/`: `/api` matches `/api`, `/api/` and `/api/orders`, but not `/apiary-docs`, whose first element is `apiary-docs`. The page falls through to the second rule and reaches the web app. The misconception comes from string prefixes in old proxy configs, where `location /api` in nginx does match `/apiary-docs`.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_171') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_171'), 'The app team applies an HTTPRoute in its namespace `rice-rocket`. The platform team''s Gateway lives in `gateway-system`:

```yaml
# Gateway public (namespace gateway-system), listener https
allowedRoutes:
  namespaces:
    from: Selector
    selector:
      matchLabels:
        expose-public: "true"
```

```text
$ kubectl -n rice-rocket get httproute site -o jsonpath=''{.status.parents[0].conditions[0]}''
{"type":"Accepted","status":"False","reason":"NotAllowedByListeners"}
```

Statement: "No edit inside the HTTPRoute can fix this: the listener decides which namespaces may attach, so either `rice-rocket` gets the label `expose-public: \"true\"` or the platform team changes `allowedRoutes`."', 'single_choice'::question_type, 'True. The Gateway API splits the roles on purpose: the platform owns the GatewayClass and the Gateway, including which namespaces may attach routes to each listener, and the app team owns its HTTPRoutes. A route only asks to attach through `parentRefs`; `NotAllowedByListeners` means the listener refused it. Labelling the namespace (a cluster-level action) or changing `allowedRoutes` fixes it. The misconception is that the route owner can grant itself access by pointing `parentRefs` at the Gateway.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_171') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
