    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_171'), 'Every request to `https://api.ricerocket.vn` answers 500 after a change to the `api` route:

```yaml
# Service api: port 80, targetPort http (containerPort 3000)
rules:
  - backendRefs:
      - name: api
        port: 3000
```

```text
$ kubectl -n rice-rocket describe httproute api | grep -A2 ResolvedRefs
    Reason:  BackendNotFound
    Status:  False
    Type:    ResolvedRefs
```

Statement: "A `backendRef` names a port of the Service, not of the container: the Service `api` exposes 80, so the route must say `port: 80` and the Service forwards to the container''s 3000."', 'single_choice'::question_type, 'True. A backendRef points at a Service, and `port` is one of that Service''s ports. The Service exposes 80 and maps it to its `targetPort` (the container port named `http`, 3000). The Service has no port 3000, so the reference does not resolve, and the spec has the gateway answer 500 for requests to an unresolved backend. The misconception is that the route talks to the pods directly.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_171') AND order_index = 3)
    RETURNING id
)
