INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_k8s_172', (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-k8s-3-1' AND is_deleted = false LIMIT 1), 'gateway-tls-routes', 'Route ricerocket.vn through the Gateway API', 'Rice Rocket''s routing moves off the retired ingress-nginx controller to the Gateway API. The editor holds `k8s/routes.yaml` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: the Gateway `public` (GatewayClass `managed`) has an HTTPS listener on 443 that terminates TLS with the Secret `ricerocket-tls`, and an HTTP listener on 80 used only for redirects; every `http://` request gets a 301 to the same URL on `https://`; on `ricerocket.vn`, `/api` and every path below it reach the Service `api` with `/api` removed, and every other path reaches the Service `web`. Both Services expose port 80. Run grades the file with a simulator of Gateway API listener selection, route attachment, match precedence and filters.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
