INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_181'), 1, 'After a restart there are two containers in the story: the one running now and the one that died. Which one does `kubectl logs` read by default, and which flag reads the other?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_181'), 2, 'Compare `state.waiting.reason` with `lastState.terminated.reason`. One tells you what the kubelet is doing now, the other what happened to the last run.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_181'), 3, 'Some failures happen before the process starts at all. Would restarting the container change the Secret it reads?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_181');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_181'), 'The api pod has restarted four times. The engineer runs:

```text
$ kubectl get pod api-7b9c6d5f4-k2x8p -n rice-rocket
NAME                  READY   STATUS             RESTARTS      AGE
api-7b9c6d5f4-k2x8p   0/1     CrashLoopBackOff   4 (31s ago)   3m12s
$ kubectl logs api-7b9c6d5f4-k2x8p -n rice-rocket
{"level":30,"msg":"loading config"}
```

Statement: "`kubectl logs` without flags shows the output of the container that crashed, so the crash happened right after `loading config` and printed nothing."', 'single_choice'::question_type, 'False. `kubectl logs` reads the **current** container: the one the kubelet started after the last crash, which has only just begun (or is waiting in back-off). The run that died is read with `kubectl logs api-7b9c6d5f4-k2x8p --previous`. Its last lines usually hold the error. The misconception is that a pod has one log across restarts.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_181') AND order_index = 1)
    RETURNING id
)
