    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_181'), '`kubectl describe pod` for the same pod shows:

```text
    State:          Waiting
      Reason:       CrashLoopBackOff
    Last State:     Terminated
      Reason:       Error
      Exit Code:    1
    Restart Count:  4
Events:
  Normal   Pulled   2m   kubelet  Container image "ghcr.io/rice-rocket/api:1.5.0" already present on machine
  Warning  BackOff  31s  kubelet  Back-off restarting failed container api in pod api-7b9c6d5f4-k2x8p
```

Statement: "CrashLoopBackOff is not the cause. It means the kubelet is waiting longer and longer (up to 5 minutes) between restarts; the cause is in Last State (exit code 1: the app exited with an error) and in the previous container''s log."', 'single_choice'::question_type, 'True. `CrashLoopBackOff` is a waiting reason: the container keeps exiting, so the kubelet restarts it with an exponential back-off (10s, 20s, 40s, ... capped at 5 minutes). It says nothing about why. `Last State: Terminated` holds the exit code and reason of the run that died: 1 is an error from the app itself, 137 with `OOMKilled` is the memory limit, 137 or 143 after `failed liveness probe` events is the kubelet killing it. The misconception is to search the internet for "CrashLoopBackOff" as if it were an error message.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_k8s_181') AND order_index = 2)
    RETURNING id
)
