-- challenge chal_coding_k8s_182 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_k8s_182', (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-k8s-3-2' AND is_deleted = false LIMIT 1), 'pod-triage-script', 'Fix the pod triage script', 'Rice Rocket''s on-call bot runs `runbooks/triage.js` on every pod that is not ready and posts its answer in the incident channel. Last week it gave wrong advice four times: it quoted the log of the fresh container instead of the one that died, called an OOMKilled api an app crash, missed ImagePullBackOff and CreateContainerConfigError entirely, and never noticed that the kubelet was killing the api for failed liveness probes. The editor holds the fixed script with its key blocks missing, each marked by a `// [ ]` line; some pieces are last week''s buggy versions. `triage(pod, events, logs)` gets `kubectl get pod -o json`, the pod''s events (oldest first) and `{ current, previous }` logs, and must return `{ cause, evidence, next }` for the first container whose `ready` is false (`Healthy`, "all containers ready", "nothing to do" when there is none), checking in this order: `state.waiting.reason` `ImagePullBackOff` or `ErrImagePull` (cause `ImagePullBackOff`) and `CreateContainerConfigError`, both with the waiting message as evidence; `lastState.terminated.reason` `OOMKilled` (evidence `exit code <code> (OOMKilled) after <restartCount> restarts`); a `Killing` event whose message says `failed liveness probe` (cause `LivenessProbe`, evidence the last event message starting with `Liveness probe failed`); otherwise, if the container has a last state or restarts, `AppError` with the last non-empty line of the previous log (or `exit code <code>`); otherwise `Starting` with the waiting reason. `next` comes from the `NEXT` table. Run grades it on recorded pods.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_182');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_182'), 1, 'For each recorded pod, write down which field holds the answer: `state.waiting`, `lastState.terminated` or the events. Which of them did last week''s script never read?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_182'), 2, 'The order matters: a container that was never created has no last state; an OOM kill and a liveness kill both end with a non-zero exit code, but only one of them has a `reason` that says so; the events tell the other one apart.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_182'), 3, 'A triage for a node instead of a pod: `const pressure = node.status.conditions.find((c) => c.type === "MemoryPressure" && c.status === "True"); if (pressure) return { cause: "MemoryPressure", evidence: pressure.message };` and for the kubelet log it reads the last line of the **previous** boot (`journalctl -b -1`), not the current one.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_182'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"pick-container","label":"The first container that is not ready, or Healthy","code":"const status = statuses.find((s) => !s.ready);\nif (!status) return { cause: \"Healthy\", evidence: \"all containers ready\", next: \"nothing to do\" };"},{"id":"waiting-reasons","label":"Containers that never started: image or config","code":"if (waiting && (waiting.reason === \"ImagePullBackOff\" || waiting.reason === \"ErrImagePull\")) {\n    return { cause: \"ImagePullBackOff\", evidence: waiting.message, next: NEXT.ImagePullBackOff };\n}\nif (waiting && waiting.reason === \"CreateContainerConfigError\") {\n    return { cause: \"CreateContainerConfigError\", evidence: waiting.message, next: NEXT.CreateContainerConfigError };\n}"},{"id":"oom-killed","label":"The last run was killed at its memory limit","code":"if (last && last.reason === \"OOMKilled\") {\n    return {\n        cause: \"OOMKilled\",\n        evidence: `exit code ${last.exitCode} (OOMKilled) after ${status.restartCount} restarts`,\n        next: NEXT.OOMKilled,\n    };\n}"},{"id":"liveness-kill","label":"The kubelet restarted it after failed liveness probes","code":"const killed = events.some((e) => e.reason === \"Killing\" && /failed liveness probe/.test(e.message));\nif (killed) {\n    const probe = events.filter((e) => /^Liveness probe failed/.test(e.message)).pop();\n    return { cause: \"LivenessProbe\", evidence: probe ? probe.message : \"failed liveness probe\", next: NEXT.LivenessProbe };\n}"},{"id":"app-error-evidence","label":"Why the app exited: the log of the run that died","code":"const line = lastLine(logs.previous);\nreturn { cause: \"AppError\", evidence: line || `exit code ${last ? last.exitCode : \"unknown\"}`, next: NEXT.AppError };"},{"id":"app-error-current-log","label":"Why the app exited: the log of the run that died","code":"const line = lastLine(logs.current);\nreturn { cause: \"AppError\", evidence: line || `exit code ${last ? last.exitCode : \"unknown\"}`, next: NEXT.AppError };","distractor":true},{"id":"liveness-exit-reason","label":"The kubelet restarted it after failed liveness probes","code":"if (last && last.reason === \"Liveness\") {\n    return { cause: \"LivenessProbe\", evidence: \"failed liveness probe\", next: NEXT.LivenessProbe };\n}","distractor":true},{"id":"oom-current-state","label":"The last run was killed at its memory limit","code":"const now = (status.state && status.state.terminated) || null;\nif (now && now.reason === \"OOMKilled\") {\n    return {\n        cause: \"OOMKilled\",\n        evidence: `exit code ${now.exitCode} (OOMKilled) after ${status.restartCount} restarts`,\n        next: NEXT.OOMKilled,\n    };\n}","distractor":true},{"id":"waiting-terminated-only","label":"Containers that never started: image or config","code":"const current = (status.state && status.state.terminated) || null;\nif (current && (current.reason === \"ImagePullBackOff\" || current.reason === \"ErrImagePull\")) {\n    return { cause: \"ImagePullBackOff\", evidence: current.message, next: NEXT.ImagePullBackOff };\n}\nif (current && current.reason === \"CreateContainerConfigError\") {\n    return { cause: \"CreateContainerConfigError\", evidence: current.message, next: NEXT.CreateContainerConfigError };\n}","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
