INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_182'), 'A tag that does not exist: ImagePullBackOff with the kubelet''s message', '{"pod":{"metadata":{"name":"api-5f8b7c6d9-wq2lm","namespace":"rice-rocket"},"status":{"phase":"Running","containerStatuses":[{"name":"api","ready":false,"restartCount":0,"state":{"waiting":{"reason":"ImagePullBackOff","message":"Back-off pulling image \"ghcr.io/rice-rocket/api:1.5.1\""}},"lastState":{}}]}},"events":[{"type":"Warning","reason":"Failed","message":"Failed to pull image \"ghcr.io/rice-rocket/api:1.5.1\": ghcr.io/rice-rocket/api:1.5.1: not found"},{"type":"Normal","reason":"BackOff","message":"Back-off pulling image \"ghcr.io/rice-rocket/api:1.5.1\""}],"logs":{"current":"","previous":""}}', '{"cause":"ImagePullBackOff","evidence":"Back-off pulling image \"ghcr.io/rice-rocket/api:1.5.1\"","next":"fix the image name or tag, or the pull secret, then roll out again"}', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_182'), 'Killed at the memory limit during the report export: OOMKilled, not an app crash', '{"pod":{"metadata":{"name":"api-7b9c6d5f4-k2x8p","namespace":"rice-rocket"},"status":{"phase":"Running","containerStatuses":[{"name":"api","ready":false,"restartCount":4,"state":{"waiting":{"reason":"CrashLoopBackOff","message":"back-off 1m20s restarting failed container=api"}},"lastState":{"terminated":{"exitCode":137,"reason":"OOMKilled","finishedAt":"2026-11-03T02:12:07Z"}}}]}},"events":[{"type":"Warning","reason":"BackOff","message":"Back-off restarting failed container api in pod api-7b9c6d5f4-k2x8p"}],"logs":{"current":"{\"level\":30,\"msg\":\"loading config\"}","previous":"{\"level\":30,\"msg\":\"export: 410000 rows\"}\n{\"level\":30,\"msg\":\"export: 820000 rows\"}"}}', '{"cause":"OOMKilled","evidence":"exit code 137 (OOMKilled) after 4 restarts","next":"raise limits.memory or fix the memory growth; compare with kubectl top pod"}', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_182'), 'A Secret key that does not exist: CreateContainerConfigError, no restart helps', '{"pod":{"metadata":{"name":"api-6d8f7c9b5-zt4qw","namespace":"rice-rocket"},"status":{"phase":"Running","containerStatuses":[{"name":"api","ready":false,"restartCount":0,"state":{"waiting":{"reason":"CreateContainerConfigError","message":"couldn''t find key db_password in Secret rice-rocket/api-secrets"}},"lastState":{}}]}},"events":[{"type":"Warning","reason":"Failed","message":"Error: couldn''t find key db_password in Secret rice-rocket/api-secrets"}],"logs":{"current":"","previous":""}}', '{"cause":"CreateContainerConfigError","evidence":"couldn''t find key db_password in Secret rice-rocket/api-secrets","next":"fix the ConfigMap or Secret the pod refers to; a restart will not help"}', 5, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_182'), 'The kubelet kills api for failed liveness probes; the ready sidecar is skipped', '{"pod":{"metadata":{"name":"api-8c7d6e5f4-p9r2t","namespace":"rice-rocket"},"status":{"phase":"Running","containerStatuses":[{"name":"log-shipper","ready":true,"restartCount":0,"state":{"running":{"startedAt":"2026-11-04T08:00:02Z"}},"lastState":{}},{"name":"api","ready":false,"restartCount":3,"state":{"waiting":{"reason":"CrashLoopBackOff","message":"back-off 1m20s restarting failed container=api"}},"lastState":{"terminated":{"exitCode":137,"reason":"Error","finishedAt":"2026-11-04T08:03:40Z"}}}]}},"events":[{"type":"Warning","reason":"Unhealthy","message":"Liveness probe failed: Get \"http://10.0.1.23:3000/ready\": context deadline exceeded (Client.Timeout exceeded while awaiting headers)"},{"type":"Warning","reason":"Unhealthy","message":"Liveness probe failed: HTTP probe failed with statuscode: 503"},{"type":"Normal","reason":"Killing","message":"Container api failed liveness probe, will be restarted"}],"logs":{"current":"{\"level\":30,\"msg\":\"listening on 3000\"}","previous":"{\"level\":30,\"msg\":\"listening on 3000\"}\n{\"level\":40,\"msg\":\"db pool exhausted, waiting\"}"}}', '{"cause":"LivenessProbe","evidence":"Liveness probe failed: HTTP probe failed with statuscode: 503","next":"check the liveness probe path, port and timing against the app''s startup"}', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_182'), 'An app error: the evidence is the last line of the container that died', '{"pod":{"metadata":{"name":"api-9d8e7f6a5-m3n4b","namespace":"rice-rocket"},"status":{"phase":"Running","containerStatuses":[{"name":"api","ready":false,"restartCount":2,"state":{"waiting":{"reason":"CrashLoopBackOff","message":"back-off 1m20s restarting failed container=api"}},"lastState":{"terminated":{"exitCode":1,"reason":"Error","finishedAt":"2026-11-05T10:15:02Z"}}}]}},"events":[{"type":"Warning","reason":"BackOff","message":"Back-off restarting failed container api in pod api-9d8e7f6a5-m3n4b"}],"logs":{"current":"","previous":"{\"level\":30,\"msg\":\"loading config\"}\nfatal: config: JWT_SECRET_FILE /run/secrets/jwt_secret is empty\n"}}', '{"cause":"AppError","evidence":"fatal: config: JWT_SECRET_FILE /run/secrets/jwt_secret is empty","next":"fix the error from the previous container''s log"}', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_182'), 'A pod still creating its container is Starting, not an error', '{"pod":{"metadata":{"name":"web-5b6c7d8e9-h7j8k","namespace":"rice-rocket"},"status":{"phase":"Running","containerStatuses":[{"name":"nginx","ready":false,"restartCount":0,"state":{"waiting":{"reason":"ContainerCreating"}},"lastState":{}}]}},"events":[{"type":"Normal","reason":"Pulling","message":"Pulling image \"ghcr.io/rice-rocket/web:2.3.0\""}],"logs":{"current":"","previous":""}}', '{"cause":"Starting","evidence":"ContainerCreating","next":"wait for the readiness probe; describe the pod if it stays not ready"}', 5, false, true, 6);
