-- challenge chal_coding_k8s_192 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_k8s_192', (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'kubernetes-deploy-and-operate') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-k8s-3-3' AND is_deleted = false LIMIT 1), 'migration-job-nightly-cronjob', 'Run the migration as a Job and the cleanup as a CronJob', 'Rice Rocket''s migrations used to run in the api''s start command, so six replicas raced on the same migration. Release 1.5.0 moves them into a Job that CI applies and waits for before it changes the api image, and moves the cart cleanup into a nightly CronJob. The editor holds `k8s/jobs.yaml` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: a failed migration is retried once in a new pod (so the failed pod''s logs stay readable) and the Job gives up after 5 minutes in any case; the finished Job and its pods are deleted a day later; the cleanup runs every night at 03:00 Ho Chi Minh City time (the cluster''s controllers run in UTC), never twice at the same time, never more than 10 minutes late, and is stopped after one hour. Run grades the file with a simulator of the Job and CronJob controllers.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_192');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_192'), 1, 'Work through the timelines in the tests: for the Job, count pods and seconds until it is Complete or Failed; for the CronJob, write down the local time of each run and what happens when one hangs or the controller is down at 03:00.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_192'), 2, 'Look at the Job fields `backoffLimit`, `activeDeadlineSeconds`, `ttlSecondsAfterFinished` and the pod''s `restartPolicy`, and at the CronJob fields `schedule`, `timeZone`, `concurrencyPolicy`, `startingDeadlineSeconds` and the `activeDeadlineSeconds` inside `jobTemplate.spec`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_192'), 3, 'A weekly report for a team in Berlin, Mondays at 07:30 local time, never overlapping, skipped when it is more than 5 minutes late, a run stopped after 20 minutes: `schedule: "30 7 * * 1"`, `timeZone: Europe/Berlin`, `concurrencyPolicy: Forbid`, `startingDeadlineSeconds: 300`, and `activeDeadlineSeconds: 1200` under `jobTemplate.spec`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_k8s_192'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"job-retries","label":"Retry a failed migration once, and stop it after 5 minutes","code":"backoffLimit: 1\nactiveDeadlineSeconds: 300"},{"id":"job-cleanup","label":"Delete the finished Job and its pods a day later","code":"ttlSecondsAfterFinished: 86400"},{"id":"job-restart-policy","label":"A failed attempt gets a new pod, its logs stay readable","code":"restartPolicy: Never"},{"id":"cron-schedule","label":"Every night at 03:00 Ho Chi Minh City time","code":"schedule: \"0 3 * * *\"\ntimeZone: Asia/Ho_Chi_Minh"},{"id":"cron-concurrency","label":"One run at a time; skip a run more than 10 minutes late","code":"concurrencyPolicy: Forbid\nstartingDeadlineSeconds: 600"},{"id":"cron-run-deadline","label":"Stop a nightly run that takes longer than one hour","code":"activeDeadlineSeconds: 3600"},{"id":"cron-concurrency-no-deadline","label":"One run at a time; skip a run more than 10 minutes late","code":"concurrencyPolicy: Forbid","distractor":true},{"id":"cron-schedule-no-time-zone","label":"Every night at 03:00 Ho Chi Minh City time","code":"schedule: \"0 3 * * *\"","distractor":true},{"id":"job-retries-default","label":"Retry a failed migration once, and stop it after 5 minutes","code":"backoffLimit: 6","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
